//! Checks the port against js-yaml's recorded behaviour (`conformance/fixtures/*.json`,
//! generated by `just sync-upstream`).
//!
//! The port starts at zero, so this is a ratchet: every case listed in
//! `conformance/passing.txt` must pass, and cases that pass but aren't listed are reported.
//! `CONFORMANCE_REPORT=1` prints every failure; `CONFORMANCE_BLESS=1` rewrites
//! `passing.txt` with everything that passes now (review the diff: it must only grow).

#![cfg(feature = "serde")]
#![allow(clippy::unwrap_used)]

use std::collections::{BTreeSet, HashMap};
use std::fmt::Write as _;
use std::path::PathBuf;

use jsyaml::utf16::Utf16Cursor;
use jsyaml::{
    CollectionEvent, ConstructorOptions, Directive, Document, Error, Event, LoadOptions,
    ParserOptions, Schema, Span, Value, get_scalar_value, load_all, parse_events,
};
use serde_json::{Map, Value as Json, json};

fn conformance_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../conformance")
}

fn fixture(name: &str) -> Vec<Json> {
    let path = conformance_dir().join(format!("fixtures/{name}.json"));
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e} (run `just sync-upstream`)", path.display()));
    serde_json::from_str(&text).unwrap()
}

#[test]
fn upstream_conformance() {
    let passing_path = conformance_dir().join("passing.txt");
    let listed: BTreeSet<String> = std::fs::read_to_string(&passing_path)
        .unwrap_or_default()
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(String::from)
        .collect();
    let verbose = std::env::var_os("CONFORMANCE_REPORT").is_some();

    let mut passed = BTreeSet::new();
    let mut failures = Vec::new();
    let mut skipped = 0;

    for case in fixture("events") {
        if is_native_error(&case) {
            skipped += 1;
            continue;
        }
        let id = format!("events::{}", case["id"].as_str().unwrap());
        record(id, check_events(&case), &mut passed, &mut failures);
    }
    for case in fixture("load") {
        if is_native_error(&case) {
            skipped += 1;
            continue;
        }
        let id = format!(
            "load::{}::{}",
            case["schema"].as_str().unwrap(),
            case["id"].as_str().unwrap()
        );
        record(id, check_load(&case), &mut passed, &mut failures);
    }

    let regressions: Vec<_> = failures
        .iter()
        .filter(|(id, _)| listed.contains(id))
        .collect();
    let newly_passing: Vec<_> = passed.difference(&listed).collect();
    let total = passed.len() + failures.len();

    let mut report = String::new();
    writeln!(report, "## Conformance vs js-yaml {}", upstream_version()).unwrap();
    writeln!(
        report,
        "\n{} / {total} passing, {skipped} skipped (non-YAML errors)",
        passed.len()
    )
    .unwrap();
    for prefix in ["events::", "load::core::", "load::json::", "load::yaml11::"] {
        let p = passed.iter().filter(|id| id.starts_with(prefix)).count();
        let f = failures
            .iter()
            .filter(|(id, _)| id.starts_with(prefix))
            .count();
        writeln!(report, "- `{prefix}`: {p} / {}", p + f).unwrap();
    }
    if verbose {
        for (id, why) in &failures {
            writeln!(report, "\nFAIL {id}\n{why}").unwrap();
        }
    }
    println!("{report}");

    if std::env::var_os("CONFORMANCE_BLESS").is_some() {
        let mut text = String::from(
            "# Conformance cases that pass and must keep passing. Regenerate with\n\
             # `just conformance-bless`; the list should only grow.\n",
        );
        for id in &passed {
            text.push_str(id);
            text.push('\n');
        }
        std::fs::write(&passing_path, text).unwrap();
        return;
    }
    if !newly_passing.is_empty() {
        println!(
            "{} cases pass but aren't in passing.txt; run `just conformance-bless`.",
            newly_passing.len()
        );
    }
    assert!(
        regressions.is_empty(),
        "{} listed cases regressed:\n{}",
        regressions.len(),
        regressions
            .iter()
            .map(|(id, why)| format!("{id}: {why}"))
            .collect::<Vec<_>>()
            .join("\n")
    );
}

fn record(
    id: String,
    result: Result<(), String>,
    passed: &mut BTreeSet<String>,
    failures: &mut Vec<(String, String)>,
) {
    match result {
        Ok(()) => {
            passed.insert(id);
        }
        Err(why) => failures.push((id, why)),
    }
}

fn upstream_version() -> String {
    std::fs::read_to_string(conformance_dir().join("UPSTREAM_VERSION"))
        .unwrap()
        .trim()
        .to_owned()
}

/// Upstream threw something other than a `YAMLException` (e.g. a stack overflow).
fn is_native_error(case: &Json) -> bool {
    case["error"]["native"].as_bool() == Some(true)
}

fn check_events(case: &Json) -> Result<(), String> {
    let input = case["yaml"].as_str().unwrap();
    let result = parse_events(input, &ParserOptions::default());
    match (&case["error"], result) {
        (Json::Null, Ok(events)) => {
            let actual = Json::Array(encode_events(input, &events));
            compare(&case["events"], &actual)?;
            let scalars: Vec<Json> = events
                .iter()
                .filter_map(|e| match e {
                    Event::Scalar(s) => Some(json!(get_scalar_value(input, s))),
                    _ => None,
                })
                .collect();
            compare(&case["scalars"], &Json::Array(scalars))
        }
        (Json::Null, Err(e)) => Err(format!("unexpected error: {e}")),
        (expected, Err(e)) => compare_error(input, expected, &e),
        (expected, Ok(_)) => Err(format!("expected error {expected}, got events")),
    }
}

fn check_load(case: &Json) -> Result<(), String> {
    let input = case["yaml"].as_str().unwrap();
    let schema = match case["schema"].as_str().unwrap() {
        "core" => Schema::core(),
        "json" => Schema::json(),
        "yaml11" => Schema::yaml11(),
        other => return Err(format!("unknown schema {other}")),
    };
    let options = LoadOptions {
        parser: ParserOptions::default(),
        constructor: ConstructorOptions {
            schema,
            ..ConstructorOptions::default()
        },
    };
    match (&case["error"], load_all(input, &options)) {
        (Json::Null, Ok(documents)) => {
            let actual = Json::Array(documents.iter().map(encode_document).collect());
            compare(&canonical(&case["documents"]), &canonical(&actual))
        }
        (Json::Null, Err(e)) => Err(format!("unexpected error: {e}")),
        (expected, Err(e)) => compare_error(input, expected, &e),
        (expected, Ok(_)) => Err(format!("expected error {expected}, got documents")),
    }
}

fn compare(expected: &Json, actual: &Json) -> Result<(), String> {
    if expected == actual {
        Ok(())
    } else {
        Err(format!("expected: {expected}\n  actual: {actual}"))
    }
}

fn compare_error(input: &str, expected: &Json, actual: &Error) -> Result<(), String> {
    let position = actual
        .position()
        .map(|p| Utf16Cursor::new(input).to_utf16(p));
    let actual = json!({ "reason": actual.reason(), "position": position });
    let expected = json!({ "reason": expected["reason"], "position": expected["position"] });
    compare(&expected, &actual)
}

// Events in upstream's object shape, with UTF-16 offsets and -1 for absent ranges.
fn encode_events(input: &str, events: &[Event]) -> Vec<Json> {
    let mut utf16 = Utf16Cursor::new(input);
    let mut range = |span: Option<Span>| match span {
        Some(s) => (json!(utf16.to_utf16(s.start)), json!(utf16.to_utf16(s.end))),
        None => (json!(-1), json!(-1)),
    };
    events
        .iter()
        .map(|event| match event {
            Event::Document(d) => json!({
                "type": event.id(),
                "explicitStart": d.explicit_start,
                "explicitEnd": d.explicit_end,
                "directives": d.directives.iter().map(|d| match d {
                    Directive::Yaml { version } => json!({ "kind": "yaml", "version": version }),
                    Directive::Tag { handle, prefix } => json!({ "kind": "tag", "handle": handle, "prefix": prefix }),
                }).collect::<Vec<_>>(),
            }),
            Event::Sequence(c) | Event::Mapping(c) => {
                let CollectionEvent { start, anchor, tag, style } = *c;
                let start = range(Some(Span { start, end: start })).0;
                let (anchor_start, anchor_end) = range(anchor);
                let (tag_start, tag_end) = range(tag);
                json!({
                    "type": event.id(), "start": start,
                    "anchorStart": anchor_start, "anchorEnd": anchor_end,
                    "tagStart": tag_start, "tagEnd": tag_end, "style": style as u8,
                })
            }
            Event::Scalar(s) => {
                let (value_start, value_end) = range(s.value);
                let (anchor_start, anchor_end) = range(s.anchor);
                let (tag_start, tag_end) = range(s.tag);
                json!({
                    "type": event.id(),
                    "valueStart": value_start, "valueEnd": value_end,
                    "anchorStart": anchor_start, "anchorEnd": anchor_end,
                    "tagStart": tag_start, "tagEnd": tag_end,
                    "style": s.style as u8, "chomping": s.chomping as u8,
                    "indent": s.indent, "fast": s.fast,
                })
            }
            Event::Alias(span) => {
                let (anchor_start, anchor_end) = range(Some(*span));
                json!({ "type": event.id(), "anchorStart": anchor_start, "anchorEnd": anchor_end })
            }
            Event::Pop => json!({ "type": event.id() }),
        })
        .collect()
}

// The typed encoding documented in scripts/extract-upstream-fixtures.mjs. Shared values
// are numbered in order of first use while walking like the JS encoder does (objects in
// `Object.keys` order), so the numbering doesn't depend on how Rust numbered them.
fn encode_document(doc: &Document) -> Json {
    let mut encoder = Encoder {
        doc,
        renumber: HashMap::new(),
        shared: Vec::new(),
    };
    let value = encoder.value(&doc.root);
    let mut out = Map::new();
    out.insert("value".into(), value);
    if !encoder.shared.is_empty() {
        out.insert("shared".into(), Json::Array(encoder.shared));
    }
    Json::Object(out)
}

struct Encoder<'a> {
    doc: &'a Document,
    renumber: HashMap<usize, usize>,
    shared: Vec<Json>,
}

impl Encoder<'_> {
    fn value(&mut self, value: &Value) -> Json {
        match value {
            Value::Null => Json::Null,
            Value::Bool(b) => json!(b),
            Value::Number(n) => encode_number(*n),
            Value::String(s) => json!(s),
            Value::Sequence(items) => items.iter().map(|v| self.value(v)).collect(),
            Value::Object(entries) => {
                let ordered = js_key_order(entries);
                let pairs: Vec<Json> = ordered
                    .iter()
                    .map(|(k, v)| json!([k, self.value(v)]))
                    .collect();
                json!({ "$object": pairs })
            }
            Value::Map(entries) => {
                let pairs: Vec<Json> = entries
                    .iter()
                    .map(|(k, v)| json!([self.value(k), self.value(v)]))
                    .collect();
                json!({ "$map": pairs })
            }
            Value::Set(items) => {
                let items: Vec<Json> = items.iter().map(|v| self.value(v)).collect();
                json!({ "$set": items })
            }
            Value::Binary(bytes) => json!({ "$binary": base64(bytes) }),
            Value::Date(ms) => json!({ "$date": ms }),
            Value::Shared(i) => {
                if let Some(&n) = self.renumber.get(i) {
                    return json!({ "$shared": n });
                }
                let n = self.shared.len();
                self.renumber.insert(*i, n);
                self.shared.push(Json::Null);
                let doc = self.doc;
                let content = self.value(&doc.shared[*i]);
                self.shared[n] = content;
                json!({ "$shared": n })
            }
        }
    }
}

fn encode_number(n: f64) -> Json {
    if n.is_nan() {
        json!({ "$number": "NaN" })
    } else if n.is_infinite() {
        json!({ "$number": if n > 0.0 { "Infinity" } else { "-Infinity" } })
    } else if n == 0.0 && n.is_sign_negative() {
        json!({ "$number": "-0" })
    } else {
        json!(n)
    }
}

/// `Object.keys` order: array-index keys ascending, then the rest in insertion order.
fn js_key_order(entries: &[(String, Value)]) -> Vec<&(String, Value)> {
    let index = |k: &str| -> Option<u32> {
        let n: u32 = k.parse().ok()?;
        (n != u32::MAX && n.to_string() == k).then_some(n)
    };
    let mut indexed: Vec<_> = entries.iter().filter(|(k, _)| index(k).is_some()).collect();
    indexed.sort_by_key(|(k, _)| index(k));
    indexed.extend(entries.iter().filter(|(k, _)| index(k).is_none()));
    indexed
}

/// Numbers compared as f64: JSON from JS writes `1`, serde writes `1.0`.
fn canonical(value: &Json) -> Json {
    match value {
        Json::Number(n) => json!(n.as_f64().unwrap()),
        Json::Array(items) => items.iter().map(canonical).collect(),
        Json::Object(map) => {
            Json::Object(map.iter().map(|(k, v)| (k.clone(), canonical(v))).collect())
        }
        other => other.clone(),
    }
}

fn base64(bytes: &[u8]) -> String {
    const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in bytes.chunks(3) {
        let n = chunk
            .iter()
            .enumerate()
            .fold(0u32, |n, (i, &b)| n | (u32::from(b) << (16 - 8 * i)));
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(ALPHABET[((n >> (18 - 6 * i)) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

#[test]
fn base64_matches_node() {
    assert_eq!(base64(b"hi"), "aGk=");
    assert_eq!(base64(b"abc"), "YWJj");
    assert_eq!(base64(b"a"), "YQ==");
}
